def transform(grid):
    bg = grid[0][0]  # background color is at corner
    num_rows = len(grid)
    num_cols = len(grid[0])

    # Initialize result with background
    result = [[bg for _ in range(num_cols)] for _ in range(num_rows)]

    for r in range(num_rows):
        # Find first and last non-background position
        first = None
        last = None
        for c in range(num_cols):
            if grid[r][c] != bg:
                if first is None:
                    first = c
                last = c

        if first is None:
            continue

        # Check if this is a "solid row" (no background between first and last)
        has_gap = False
        for c in range(first + 1, last):
            if grid[r][c] == bg:
                has_gap = True
                break

        if not has_gap:
            # Solid row - copy to same position
            for c in range(first, last + 1):
                if grid[r][c] != bg:
                    result[r][c] = grid[r][c]
        else:
            # Hollow row - shift right by 1
            for c in range(first, last):
                if grid[r][c] != bg:
                    result[r][c+1] = grid[r][c]

    return result
