def transform(grid):
    bg = grid[0][0]
    rows = len(grid)
    cols = len(grid[0])

    # Initialize result with all background
    result = [[bg] * cols for _ in range(rows)]

    for r in range(rows):
        # Find range of colored pixels in this row
        min_c = next((c for c in range(cols) if grid[r][c] != bg), None)
        max_c = max((c for c in range(cols) if grid[r][c] != bg), default=None)

        if min_c is None:
            continue

        # Check if there are any background pixels between min_c and max_c
        has_gap = any(grid[r][c] == bg for c in range(min_c + 1, max_c))

        if has_gap:
            # Hollow row - shift each colored pixel right by 1
            for c in range(min_c, max_c + 1):
                if grid[r][c] != bg and c + 1 < cols:
                    result[r][c + 1] = grid[r][c]
        else:
            # Solid row - keep in place
            for c in range(min_c, max_c + 1):
                result[r][c] = grid[r][c]

    return result
